def find_slots(busy_lists, win, duration, working):
    ivs = sorted(i for lst in busy_lists for i in lst)
    merged = []
    for s, e in ivs:
        if merged and s <= merged[-1][1]:
            merged[-1][1] = max(merged[-1][1], e)
        else:
            merged.append([s, e])
    slots, cur = [], win.start
    for s, e in merged + [[win.end, win.end]]:
        for gap in intersect((cur, s), working):
            if gap.end - gap.start >= duration: slots.append(gap)
        cur = max(cur, e)
    return slots[:10]

wheel = [[] for _ in range(120)]        # 1-second ticks, 2 minutes
def preload(bucket):
    for job in store.scan(bucket, my_shards):
        wheel[(job.fire_at - now()) % 120].append(job)
def tick():
    for job in wheel[pos]:
        if store.insert_if_absent('fired', job.id):
            notify.enqueue(job)
    wheel[pos].clear(); pos = (pos + 1) % 120
